import {Effect} from 'effect';
import {goTo, sell, salvage, disengage, note, orient} from 'play';

export default Effect.gen(function* () {
  while (true) {
    const res = yield* salvage().pipe(
      Effect.catchTag('NoWreck', (e) => Effect.as(note('no wreck'), {done: true as const, left: null})),
      Effect.catchTag('InBattle', (e) =>
        Effect.gen(function* () {
          yield* disengage();
          const r = yield* salvage().pipe(Effect.either);
          if (r._tag === 'Left') {
            yield* Effect.fail(r.left);
          } else {
            return {done: false as const, res: r.right};
          }
        }),
      ),
      Effect.catchTag('HoldFull', () =>
        Effect.gen(function* () {
          yield* goTo('sol_base');
          const here = yield* orient();
          yield* sell(here.cargo.map((row) => ({item_id: row.item_id})));
          yield* goTo('sol_debris');
          const r = yield* salvage().pipe(Effect.either);
          if (r._tag === 'Left') {
            yield* Effect.fail(r.left);
          } else {
            return {done: false as const, res: r.right};
          }
        }),
      ),
    );

    if (res.done === true && res.left === null) {
      return;
    }
    if (res.done === false && res.res) {
      // We completed a salvage cycle, loop again.
      continue;
    }
    // This point should be unreachable, but bail out safely.
    return;
  }
}).pipe(Effect.ensuring(disengage()));
