import {salvage, disengage, goTo, sell, orient, note, isError, sleep} from 'play';

export default async function main() {
  const scavenge = async (): Promise<boolean> => {
    // Return true when salvage succeeded, false when it failed for a reason
    // the caller should treat as "stop" (no wreck / nothing to salvage).
    for (;;) {
      try {
        await salvage();
        return true;
      } catch (e) {
        if (isError(e, 'NoWreck')) {
          note('no wreck');
          return false;
        }
        if (isError(e, 'InBattle')) {
          await disengage();
          await sleep(250);
          continue;
        }
        if (isError(e, 'HoldFull')) {
          // Go to base, sell everything, come back, then salvage again.
          await goTo('sol_base');
          const hold = (await orient()).cargo;
          await sell(hold.map(r => ({item_id: r.item_id})));
          await goTo('sol_debris');
          continue;
        }
        throw e; // not ours to handle: let it fail the program
      }
    }
  };

  await scavenge();
}
