import {Effect, Schema} from 'effect';
import {orient, readMarket, sell, note, MarketBook} from 'play';

export default Effect.gen(function* () {
  const [here, rawBook] = yield* Effect.all([orient(), readMarket()], {concurrency: 'unbounded'});

  const decoded = yield* Schema.decodeUnknown(MarketBook)(rawBook).pipe(
    Effect.catchTags({ParseError: () => Effect.void}),
  );

  if (decoded === null) {
    yield* note('bad book');
    return;
  }

  const buy = new Map<string, number>();
  for (const row of decoded.rows) {
    buy.set(row.item_id, row.best_buy);
  }

  const toSell = here.cargo
    .filter((r) => (buy.get(r.item_id) ?? 0) >= 10)
    .map((r) => ({item_id: r.item_id, quantity: r.quantity}));

  if (toSell.length > 0) {
    yield* sell(toSell);
  }
});
