import {
  note,
  isError,
  tagOf,
  orient,
  missions,
  acceptMission,
  completeMissions,
} from 'play';

export default async function main() {
  await orient();

  const list = await missions();
  const want = list.filter((m) => m.reward >= 100);

  let accepted = 0;
  for (const m of want) {
    try {
      await acceptMission(m.id);
      accepted++;
    } catch (e) {
      if (isError(e, 'NoSlots')) {
        note('no mission slots left; stopping');
        break;
