import {
  goTo,
  mine,
  sell,
  service,
  completeMissions,
  note,
  orient,
  disengage,
  isError,
  tagOf,
} from 'play';

export default async function main() {
  try {
    // 1. Go to kepler_belt
    await goTo('kepler_belt');

    // 2. Mine until the hold is full; disengage on pirates, then keep going
    for (;;) {
      try {
        await mine();
      } catch (e) {
        if (isError(e, 'HoldFull')) break;          // stop: hold full
        if (isError(e, 'InBattle')) {
          await disengage();                         // fight me, come back
          continue;
        }
        if (isError(e, 'NotAtBelt')) {
          await goTo('kepler_belt');
          continue;
        }
        throw e;                                    // not ours to handle
      }
    }

    // 3. Go to kepler_base
    await goTo('kepler_base');

    // 4. Sell copper_ore (everything of it in the hold)
    await sell([{ item_id: 'copper_ore' }]);

    // 5. Service the ship
    await service();

    // 6. Complete missions, but NothingCompletable is fine
    try {
      await completeMissions();
    } catch (e) {
      if (!isError(e, 'NothingCompletable')) throw e;
    }
  } catch (e) {
    // A step failed — still fall through to the required final note
    note(`a step failed: ${tagOf(e)}`);
  }

  // 7. Always: the last thing the program does is note current credits
  const here = await orient();
  note(`credits: ${here.credits}`);
}
