export default async function main() {
  // Mine until the hold is full. HoldFull signals the hold cannot take more;
  // any other error is not one we have a plan for, so let it fail the program.
  for (;;) {
    try {
      await mine();
    } catch (e) {
      if (isError(e, 'HoldFull')) break;
      throw e;
    }
  }

  // Fly to the base and dock.
  await goTo('sol_base');

  // Sell everything in the hold: name every cargo row, omit quantity for all of it.
  const here = await orient();
  await sell(here.cargo.map(r => ({item_id: r.item_id})));
}

