import {Effect, Schema} from 'effect';
import {orient, sell, readMarket, note, MarketBook, InBattle, NotDocked, NoBuyer} from 'play';

export default Effect.gen(function* () {
  const here = yield* orient();
  if (here.cargo.length === 0) return;

  const raw = yield* readMarket();
  const decoded = yield* Schema.decodeUnknown(MarketBook)(raw).pipe(
    Effect.catchTag('ParseError', () => Effect.zipRight(note('bad book'), Effect.succeed(null as null))),
  );

  if (decoded === null) return;

  const bestBuy = new Map<string, number>(decoded.rows.map(r => [r.item_id, r.best_buy]));
  const want = here.cargo.filter(r => (bestBuy.get(r.item_id) ?? 0) >= 10);
  if (want.length === 0) return;

  const rows = want.map(r => ({item_id: r.item_id}));
  yield* sell(rows).pipe(
    Effect.catchAll(e => {
      if (e instanceof InBattle) return Effect.fail(e);
      if (e instanceof NotDocked) return Effect.fail(e);
      // NoBuyer: only happens if nothing of what we named sold; nothing better to do — note and move on
      return Effect.zipRight(note('no buyer'), Effect.void);
    }),
  );
}).pipe(
  Effect.catchTags({
    InBattle: () => Effect.void,
    NotDocked: () => Effect.void,
  }),
);
