  base: {type: 'string'},
  rows: {
    type: 'array',
    items: {
      item_id: {type: 'string'},
      best_buy: {type: 'number', raw: 'string'},
      best_sell: {type: 'number', raw: 'string'},
    },
  },
} as const;

