    for (let attempt = 0; ; attempt++) {
      try {
        await goTo('kepler_belt');
        break;
      } catch (e) {
        if (isError(e, 'ServerBusy')) {
          await sleep(e.retryAfterMs ?? 1000);
          if (attempt >= 8) throw e; // enough retries; bail
          continue;
        }
        throw e; // InBattle / UnknownPlace / NoFuel / anything else
      }
    }

