    for (;;) {
      let holdFull = false;
      try {
        await mine();
      } catch (e) {
        if (isError(e, 'HoldFull')) {
          holdFull = true;
        } else if (isError(e, 'InBattle')) {
          await disengage();
        } else {
          throw e; // NotAtBelt / anything else
        }
