      if (holdFull) break;
    }

    // 3. Go to kepler_base, selling copper_ore.
    await goTo('kepler_base');
    await sell([{item_id: 'copper_ore'}]);

    // 4. Service the ship.
    await service();

    // 5. Complete missions, ignoring NothingCompletable.
    try {
      await completeMissions();
    } catch (e) {
      if (!isError(e, 'NothingCompletable')) throw e;
    }
