    let credits = -1;
    try {
      credits = (await orient()).credits;
    } catch (e) {
      if (!isError(e, 'ServerBusy')) {
        note(`could not read credits: ${e instanceof Error ? e.message : String(e)}`);
      }
    }
    note(`credits: ${credits}`);
  }
}
