import {Effect} from 'effect';
import {
  goTo,
  mine,
  sell,
  service,
  completeMissions,
  disengage,
  orient,
  note,
  type GameError,
} from 'play';

export default Effect.gen(function* () {
  try {
    // Fly to the kepler belt. We are free to fail here (e.g. no fuel, server busy,
    // an engaging we don't have a plan for); the ensure block records our credits either way.
    yield* goTo('kepler_belt');

    // Mine until the hold is full. A battle pauses mining: disengage, then keep going.
    while (true) {
      const step = yield* mine().pipe(Effect.either);
      if (Effect.isLeft(step)) {
        const err = step.left;
        if (err._tag === 'HoldFull') break;                       // hold full: stop
        if (err._tag === 'InBattle') {                           // pirates: bail out and resume
          yield* disengage();
          continue;
        }
        return yield* Effect.fail(err);                          // not ours: fail; ensure will log
      }
    }

    // Deliver the cargo.
    yield* goTo('kepler_base');

    // Sell our copper_ore (Name every row; here we know the belt only yields copper_ore).
    const here = yield* orient();
    const copper = here.cargo.filter((r) => r.item_id === 'copper_ore');
    if (copper.length > 0) {
      const sold = yield* sell(copper.map((r) => ({item_id: r.item_id})));
      yield* note(`sold for ${sold.total}`);
    }

    // Fix the ship.
    yield* service();

    // Turn in whatever is on the board at this base; an empty board is fine.
    yield* completeMissions().pipe(
      Effect.catchTag('NothingCompletable', () => Effect.void),
    );
  } catch (e) {
    // Whatever tripped us up, fall through to the final credits note.
  }

  const here = yield* orient();
  yield* note(`credits: ${here.credits}`);
}).pipe(Effect.ensuring(disengage()));
