  }

  const done = yield* completeMissions().pipe(
    Effect.catchTag(NothingCompletable, () =>
      Effect.as(note('nothing completable yet'), null),
    ),
  );

  if (done !== null) {
    yield* note(`completed ${done.completed.length} mission(s) for ${done.credits} credits`);
  }

  return accepted;
});
