Wait — the `catchTag(NoWreck, ...)` above resolves to a value, not a failure, so the loop can't distinguish a NoWreck that still left the generator. Let me redo this cleanly by using `Effect.either` and branching on the tag.

```ts
import {Effect, Either} from 'effect';
import {
  orient,
  salvage,
  disengage,
  note,
  goTo,
  sell,
  HoldFull,
  InBattle,
  NoWreck,
} from 'play';

export default Effect.gen(function* () {
  // We start at sol_debris, undocked, per the task.
  const here = yield* orient();

  // Keep looting the debris field until the server tells us there is no wreck left.
  while (true) {
    const res = yield* salvage().pipe(Effect.either);

    // No wreck: note it and finish successfully.
    if (Either.isLeft(res)) {
      const e = res.left;
      if (e._tag === 'NoWreck') {
        yield* note('no wreck');
        return;
      }
      // In battle: leave the fight, then go round once and salvage again.
      if (e._tag === 'InBattle') {
        yield* disengage();
        continue;
      }
      // Hold full: run a full round trip to the base, then salvage again.
      if (e._tag === 'HoldFull') {
        const spot = yield* orient();
        yield* goTo('sol_base');
        yield* sell(spot.cargo.map(r => ({item_id: r.item_id})));
        yield* goTo('sol_debris');
        continue;
      }
      // Anything else is a failure we cannot plan for: fail with it.
      return yield* Effect.fail(e);
    }

    // res is a Salvaged: we just looted whatever the field still had. Keep going.
  }
}).pipe(Effect.ensuring(disengage()));
