import {Effect, Schedule} from 'effect';
import {
  goTo,
  mine,
  sell,
  service,
  completeMissions,
  orient,
  disengage,
  note,
} from 'play';

export default Effect.gen(function* () {
  // Fly to the kepler belt.
  yield* goTo('kepler_belt').pipe(
    Effect.retry({
      schedule: Schedule.exponential('1 second'),
      times: 5,
      while: (e) => e._tag === 'ServerBusy',
    }),
  );

  // Mine until the hold is full. If pirates engage, disengage and continue.
  while (true) {
    const step = yield* mine().pipe(
      Effect.catchTag('InBattle', () => Effect.zipRight(disengage(), Effect.void)),
      Effect.either,
    );
    if (step._tag === 'Left') {
      // InBattle is handled above, so the only remaining failure is HoldFull.
      if (step.left._tag === 'HoldFull') break;
      return yield* Effect.fail(step.left);
    }
  }

  // Go to the kepler base.
  yield* goTo('kepler_base').pipe(
    Effect.catchTag('InBattle', () => Effect.zipRight(disengage(), goTo('kepler_base'))),
  );

  // Sell the copper_ore in the hold.
  const here = yield* orient();
  const copper = here.cargo.filter((r) => r.item_id === 'copper_ore');
  if (copper.length > 0) {
    yield* sell(copper);
  }

  // Service the ship.
  yield* service();

  // Complete missions, ignoring NothingCompletable.
  yield* completeMissions().pipe(
    Effect.catchTag('NothingCompletable', () => Effect.void),
  );

  // Always end by logging the current credits.
  const fin = yield* orient();
  yield* note(`credits: ${fin.credits}`);
});
