import {orient, prices, missions, note, unwrap} from 'play';

export default async function main() {
  const [here, quotes, board] = await Promise.all([orient(), prices(), missions()]);

  if (!here.ok) throw here.error;
  if (!quotes.ok) throw quotes.error;
  if (!board.ok) throw board.error;

  const q = quotes.value;
  let best: {item_id: string; best_buy: number} | null = null;
  for (const row of q) {
    if (best === null || row.best_buy > best.best_buy) best = row;
  }

  const topId = best !== null ? best.item_id : '(none)';
  note(`credits=${here.value.credits} top_item=${topId} missions=${board.value.length}`);
}
```

Notes:
- All three are issued in a single `Promise.all`, so they run concurrently rather than sequentially.
- Each `Result` is checked with `.ok` before touching `.value`; anything not `never` is rethrown with `throw r.error` (the typed way to fail the program with what wasn't handled), which also satisfies the "no casts / no ignored failures" rules.
- If no quotes are returned, the note reports `(none)` instead of failing.

