      note('no mission slots left; stopped accepting');
      break;
    }
    throw r.error;
  }

  const c = await completeMissions();
  if (!c.ok && c.error._tag === 'NothingCompletable') {
    note('nothing completable');
  } else if (!c.ok) {
    throw c.error;
  } else {
    note(`completed ${c.completed.length} mission(s), credits ${c.credits}`);
  }

  return accepted;
}
